(function() {
  'use strict';

  // 配置常量：基于文献 S038 的明确结论
  const POPULAR_UPPER_BOUND = 2.0; // 文献声称流行歌曲始终 < 2
  const DEFAULT_THRESHOLD = 2.0;

  // 工具函数：获取安全数值
  function getSafeNumber(val, defaultVal) {
    const num = Number(val);
    return isNaN(num) ? defaultVal : num;
  }

  // 初始化
  function init() {
    const slider = document.getElementById('fk-threshold');
    const thresholdValDisplay = document.getElementById('threshold-val');
    const thresholdLine = document.getElementById('threshold-line');
    const bbResult = document.querySelector('.bb-result .status');
    const msdResult = document.querySelector('.msd-result .status');
    const resetBtn = document.getElementById('reset-viz');

    // 绑定来源按钮事件 (由内核处理，此处仅确保不报错)
    const sourceBtns = document.querySelectorAll('.source-btn');
    sourceBtns.forEach(btn => {
      btn.addEventListener('click', (e) => {
        btn.style.borderColor = 'var(--accent)';
        setTimeout(() => {
          btn.style.borderColor = '';
        }, 300);
      });
    });

    // 更新逻辑
    function updateVisualization() {
      if (!slider) return;

      const currentThreshold = getSafeNumber(slider.value, DEFAULT_THRESHOLD);
      thresholdValDisplay.textContent = currentThreshold.toFixed(1);

      // 计算阈值线位置 (0-12 映射到 0-100%)
      const linePosition = (currentThreshold / 12) * 100;
      if (thresholdLine) {
        thresholdLine.style.left = linePosition + '%';
      }

      // 逻辑判断：严格基于文献提供的界限，不编造 MSD 的具体数值
      // 文献结论：BB 始终 < 2; MSD 显著高于 BB (即 > BB)

      // BB 逻辑：
      // 若门槛 >= 2.0 (已知上界)，则根据文献"始终<2"，可推断完全符合。
      // 若门槛 < 2.0，文献只说"始终<2"，未提供具体分布，故无法判断是否全部符合门槛，显示证据不足。
      let bbStatus = 'unknown';
      let bbText = '证据不足';
      if (currentThreshold >= POPULAR_UPPER_BOUND) {
        bbStatus = 'pass';
        bbText = '符合标准 (易读)';
      } else {
        bbStatus = 'unknown';
        bbText = '证据不足 (门槛低于已知上界)';
      }

      // MSD 逻辑：
      // 文献仅称"显著高于流行歌曲"，未提供具体数值或下界。
      // 无论门槛设为何值，都无法仅凭"显著更高"这一相对描述来断定 MSD 是否通过该绝对门槛。
      // 因此，MSD 的状态始终为"证据不足"，避免编造"难读"或"通过"的结论。
      let msdStatus = 'unknown';
      let msdText = '证据不足 (无具体数值)';

      // 更新 UI
      bbResult.textContent = bbText;
      bbResult.className = 'status ' + bbStatus;
      bbResult.setAttribute('data-value', bbStatus);

      msdResult.textContent = msdText;
      msdResult.className = 'status ' + msdStatus;
      msdResult.setAttribute('data-value', msdStatus);
    }

    // 复位逻辑
    function resetVisualization() {
      if (slider) {
        slider.value = DEFAULT_THRESHOLD;
        updateVisualization();
      }
    }

    // 事件监听
    if (slider) {
      slider.addEventListener('input', updateVisualization);
    }

    if (resetBtn) {
      resetBtn.addEventListener('click', resetVisualization);
    }

    // 初始运行
    updateVisualization();
  }

  // 等待 DOM 就绪
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
